/** The rotations a mission earned. */
export interface WarframeEarned {
  /** The rotations earned, in order, the latest `MAX_WARFRAME_EARNED`. */
  readonly rotations: ReadonlyArray<"A" | "B" | "C">;
  /** How many of each, all of them. */
  readonly totals: {
    /** Rotations A earned. */
    readonly A: number;
    /** Rotations B earned. */
    readonly B: number;
    /** Rotations C earned. */
    readonly C: number;
  };
}

/** The status of each Warframe feature. */
export interface WarframeFeatures {
  /** `available`, `unavailable` or `undeclared`. */
  readonly location: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly mission: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly progress: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly squad: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly eidolons: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly world: "available" | "unavailable" | "undeclared";
  /** `available`, `unavailable` or `undeclared`. */
  readonly rewards: "available" | "unavailable" | "undeclared";
}

/** The state of each Warframe feature; `null` for a feature the widget does not follow. */
export interface WarframeInfo {
  /** Where the player is; `null` while Warframe is not played. */
  readonly location: WarframeLocation | null;
  /** The latest mission of the session. */
  readonly mission: WarframeMission | null;
  /** The progress of the latest mission. */
  readonly progress: WarframeProgress | null;
  /** The squad. */
  readonly squad: WarframeSquad | null;
  /** The night on the Plains of Eidolon. */
  readonly eidolons: WarframeEidolons | null;
  /** The world of the day and the week, whether Warframe is played or not. */
  readonly world: WarframeWorld | null;
}

/** Where the player is. */
export interface WarframeLocation {
  /** What kind of place. */
  readonly kind: "orbiter" | "relay" | "hub" | "open_world" | "mission" | "dojo" | "other";
  /** Which one: a hub, a relay or an open world of our places, or the node of a mission; `null` when the game does not say. */
  readonly place: WarframeName | null;
  /** When the player arrived, in Unix milliseconds. */
  readonly since: number;
}

/** A Warframe mission. */
export interface WarframeMission {
  /** `selected` on the star chart, `loading`, `in_progress` or `ended`. */
  readonly state: "selected" | "loading" | "in_progress" | "ended";
  /** The node. */
  readonly node: WarframeNode;
  /** Its planet or region. */
  readonly planet: WarframeName | null;
  /** The mission type; `null` for one we do not know. */
  readonly type: WarframeName | null;
  /** The enemy faction. */
  readonly faction: WarframeName | null;
  /** The enemy levels of the node. */
  readonly enemyLevel: {
    /** Lowest enemy level. */
    readonly min: number;
    /** Highest enemy level. */
    readonly max: number;
  } | null;
  /** The era of a Void Fissure mission. */
  readonly fissure: WarframeName | null;
  /** What changes the mission, at most `MAX_WARFRAME_MODIFIERS`. */
  readonly modifiers: ReadonlyArray<WarframeModifier>;
  /** When it was chosen, in Unix milliseconds. */
  readonly selectedAt: number | null;
  /** When it began to load. */
  readonly loadingAt: number | null;
  /** When play began. */
  readonly startedAt: number | null;
  /** When it ended. */
  readonly endedAt: number | null;
  /** `succeeded`, `failed` or `aborted`; `null` before the end, or when the game did not say. */
  readonly result: "succeeded" | "failed" | "aborted" | null;
  /** From the start of play to the end, in seconds to the millisecond. */
  readonly durationSeconds: number | null;
  /** What the mission can reward, for a widget that follows `warframe.rewards`; `null` otherwise, for a node without a reward table, or for a mission whose table is not public or not known yet. */
  readonly rewards: WarframeRewards | null;
  /** `true` while `rewards` is `null` for now: which table applies is not known yet (a node of the day's Sortie or Archon Hunt, chosen but not loaded; the world or the drop tables not read yet). `false` otherwise, `rewards` given or not. */
  readonly rewardsPending: boolean;
  /** The rotations earned from the start, for a type with rotations; `null` otherwise or before the start. */
  readonly earned: WarframeEarned | null;
  /** The credits its end screen counts; `null` before the end, or when the game does not say (an aborted mission). */
  readonly credits: number | null;
}

/** What changes a mission. */
export interface WarframeModifier {
  /** Our ID of the modifier. */
  readonly id: "steel_path" | "arbitration" | "sortie" | "archon_hunt" | "nightmare" | "void_storm" | "alert" | "lich";
  /** Its name in the user's language. */
  readonly name: string;
  /** The stage of a Sortie or an Archon Hunt, 1 to 3, when PlayerVox OverCrow can tell it. */
  readonly stage: number | null;
}

/** The progress of a mission. */
export interface WarframeProgress {
  /** The current wave (Defense, Mirror Defense). */
  readonly wave: number | null;
  /** The enemies of the current Defense wave; `null` before the first. */
  readonly waveEnemies: {
    /** The enemies the wave announced. */
    readonly total: number;
    /** Those left, as the game counts them once all have spawned; 0 once the wave is cleared; `null` before. */
    readonly left: number | null;
  } | null;
  /** Rounds done (Interception, Disruption). */
  readonly round: number | null;
  /** Rotation rewards given so far. */
  readonly rewards: number;
  /** The rotation of the next reward; `null` for a type without rotations or one we cannot count. */
  readonly rotation: "A" | "B" | "C" | null;
  /** The rotations given so far. */
  readonly earned: WarframeEarned;
  /** The round of rotations of the next reward; `null` for a Disruption and a type without rotations. */
  readonly cycle: {
    /** 1 for the first round. */
    readonly number: number;
    /** Its rotations, in order: `A`, `A`, `B`, `C`; an Arbitration's first `A`, `A`, `B`, `B`, then `C`, `C`, `C`, `C`. */
    readonly rotations: ReadonlyArray<"A" | "B" | "C">;
    /** How many of them were given. */
    readonly earned: number;
  } | null;
  /** For a type paid on time (Survival): `waiting` until its clock starts, then `running`; `null` otherwise. */
  readonly clock: "waiting" | "running" | null;
  /** When the next reward comes, in Unix milliseconds, for a type paid on time (Survival) once its clock runs. */
  readonly nextRewardAt: number | null;
  /** The wave of the next reward, for a type paid on waves (Defense: every 3; Mirror Defense: every 2). */
  readonly nextRewardWave: number | null;
}

/** A member of the squad. */
export interface WarframeSquadMember {
  /** The player's name, without the platform icon. */
  readonly name: string;
  /** Whether it is the user. */
  readonly you: boolean;
}

/** The squad. */
export interface WarframeSquad {
  /** The members, the user included, at most `MAX_WARFRAME_SQUAD`. */
  readonly members: ReadonlyArray<WarframeSquadMember>;
}

/** One Eidolon of the night. */
export interface WarframeEidolonHunt {
  /** Which Eidolon, told by the order of the hunt; `null` when it cannot be told. */
  readonly eidolon: WarframeName | null;
  /** When it appeared, in Unix milliseconds. */
  readonly spawnedAt: number;
  /** Weak points destroyed. */
  readonly weakpoints: number;
  /** When it was captured. */
  readonly capturedAt: number | null;
  /** When it was killed. */
  readonly killedAt: number | null;
  /** When it left at dawn. */
  readonly fledAt: number | null;
}

/** The night on the Plains of Eidolon. */
export interface WarframeEidolons {
  /** Whether it is night on the Plains, as the player last saw it; `null` before. */
  readonly night: boolean | null;
  /** The Eidolons of the night, oldest first, at most `MAX_WARFRAME_HUNTS`. */
  readonly hunts: ReadonlyArray<WarframeEidolonHunt>;
}

/** One Warframe event; its type tells which state it carries. */
export type WarframeEvent = {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** What happened. */
  readonly type: "mission_selected" | "mission_loading" | "mission_started" | "mission_ended";
  /** The mission then. */
  readonly mission: WarframeMission;
} | {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** What happened. */
  readonly type: "wave_started" | "reward_given";
  /** The progress then. */
  readonly progress: WarframeProgress;
} | {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** Night or day began on the Plains. */
  readonly type: "night_started" | "day_started";
} | {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** What happened. */
  readonly type: "eidolon_spawned" | "weakpoint_destroyed" | "eidolon_captured" | "eidolon_killed" | "eidolon_fled";
  /** The Eidolon then. */
  readonly eidolon: WarframeEidolonHunt;
} | {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** What happened. */
  readonly type: "member_joined" | "member_left";
  /** Who. */
  readonly member: WarframeSquadMember;
} | {
  /** Order of the event in the subscription, from 1. */
  readonly seq: number;
  /** When it happened in the game, in Unix milliseconds. */
  readonly at: number;
  /** What happened. */
  readonly type: "location_changed";
  /** The new place. */
  readonly location: WarframeLocation;
};

/** An item a node can reward. */
export interface WarframeReward {
  /** Our ID: the item's English name in `snake_case` (`orokin_cell`). */
  readonly id: string;
  /** Its name in the user's language, or in English when PlayerVox OverCrow has no translation yet; never empty. */
  readonly name: string;
  /** How many at once. */
  readonly quantity: number;
  /** The chance, from 0 to 1; the same item's entries of a table added together. */
  readonly chance: number;
}

/** One reward table of a node. */
export interface WarframeRewardTable {
  /** `mission`, `caches` or `extra`. */
  readonly kind: "mission" | "caches" | "extra";
  /** The rotation, or `null` for a table without rotations. */
  readonly rotation: "A" | "B" | "C" | null;
  /** The items, the rarest first (equal chances by English name), at most `MAX_WARFRAME_REWARD_ITEMS`. */
  readonly items: ReadonlyArray<WarframeReward>;
}

/** What a mission can reward. */
export interface WarframeRewards {
  /** Whose tables: `node`, or the tables of their own that replace a node's: `arbitration` (every Arbitration's), `nightmare` (a Nightmare mission's reward, once, the rotation of its planet), `sortie` (a Sortie's, after its third mission). */
  readonly source: "node" | "arbitration" | "sortie" | "nightmare";
  /** The tables, at most `MAX_WARFRAME_REWARD_TABLES`. Source: Digital Extremes' drop tables, no guarantees. */
  readonly tables: ReadonlyArray<WarframeRewardTable>;
}

/** A mission of the Sortie or the Archon Hunt. */
export interface WarframeWorldMission {
  /** The node. */
  readonly node: WarframeNode;
  /** Its planet or region. */
  readonly planet: WarframeName | null;
  /** The mission type. */
  readonly type: WarframeName | null;
  /** The condition of a Sortie mission; `null` otherwise. */
  readonly modifier: WarframeName | null;
}

/** The cycle of an open world. */
export interface WarframeCycle {
  /** Day or night (Cetus), warm or cold (Orb Vallis), Fass or Vome (Cambion Drift). */
  readonly state: WarframeName;
  /** When it changes, in Unix milliseconds. */
  readonly endsAt: number;
}

/** Warframe's world of the day and the week. */
export interface WarframeWorld {
  /** When PlayerVox OverCrow last read it, in Unix milliseconds. */
  readonly updatedAt: number;
  /** The Sortie of the day. */
  readonly sortie: {
    /** The boss. */
    readonly boss: WarframeName;
    /** Its faction. */
    readonly faction: WarframeName | null;
    /** When it ends. */
    readonly endsAt: number;
    /** Its missions, in order. */
    readonly missions: ReadonlyArray<WarframeWorldMission>;
  } | null;
  /** The Archon Hunt of the week. */
  readonly archonHunt: {
    /** The Archon. */
    readonly boss: WarframeName;
    /** When it ends. */
    readonly endsAt: number;
    /** Its missions, in order. */
    readonly missions: ReadonlyArray<WarframeWorldMission>;
  } | null;
  /** The open Void Fissures, the soonest to close first, at most `MAX_WARFRAME_FISSURES`. */
  readonly fissures: ReadonlyArray<{
    /** The node. */
    readonly node: WarframeNode;
    /** Its planet or region. */
    readonly planet: WarframeName | null;
    /** The mission type. */
    readonly type: WarframeName | null;
    /** The era. */
    readonly era: WarframeName;
    /** A Steel Path fissure. */
    readonly steelPath: boolean;
    /** A Void Storm (Railjack). */
    readonly voidStorm: boolean;
    /** When it closes. */
    readonly endsAt: number;
  }>;
  /** The open worlds' cycles; `null` for one PlayerVox OverCrow cannot tell. */
  readonly cycles: {
    /** Day and night at Cetus and on the Plains. */
    readonly cetus: WarframeCycle | null;
    /** Warm and cold in the Orb Vallis. */
    readonly vallis: WarframeCycle | null;
    /** Fass and Vome in the Cambion Drift. */
    readonly cambion: WarframeCycle | null;
  };
  /** The next resets. */
  readonly resets: {
    /** The next daily reset, 00:00 UTC, in Unix milliseconds. */
    readonly daily: number;
    /** The next weekly reset, Monday 00:00 UTC. */
    readonly weekly: number;
  };
  /** Baro Ki'Teer's next visit, or the current one. */
  readonly voidTrader: {
    /** When he arrives. */
    readonly arrivesAt: number;
    /** When he leaves. */
    readonly leavesAt: number;
    /** Where he comes. */
    readonly relay: WarframeName | null;
  } | null;
  /** The Circuit's rewards of the week, when the world state gives them. */
  readonly circuit: {
    /** The rewards of the week. */
    readonly normal: ReadonlyArray<WarframeName>;
    /** The Steel Path rewards of the week. */
    readonly steelPath: ReadonlyArray<WarframeName>;
  } | null;
}

// Services.

/** Every service name. */
export type ServiceName = keyof ServiceParamsMap;

/** The parameters of each service. */
export interface ServiceParamsMap {
  /** Parameters of `subscription.cancel`. */
  readonly "subscription.cancel": {
    /** `callId` of the subscription. */
    readonly call: number;
  };
  /** Parameters of `timer.start`. */
  readonly "timer.start": {
    /** Widget-chosen timer ID, ≤ `MAX_TIMERS` active. */
    readonly timer: number;
    /** Period. */
    readonly intervalMs: number;
    /** Repeat until cancelled. */
    readonly repeat: boolean;
  };
  /** Parameters of `timer.cancel`. */
  readonly "timer.cancel": {
    /** Timer ID. */
    readonly timer: number;
  };
  /** Parameters of `storage.get`. */
  readonly "storage.get": {
    /** Key. */
    readonly key: string;
  };
  /** Parameters of `storage.set`. */
  readonly "storage.set": {
    /** Key, ≤ `MAX_STORAGE_KEYS` keys. */
    readonly key: string;
    /** JSON value ≤ `MAX_STORAGE_VALUE_BYTES`. */
    readonly value: JsonValue;
  };
  /** Parameters of `storage.remove`. */
  readonly "storage.remove": {
    /** Key. */
    readonly key: string;
  };
  /** Parameters of `storage.keys`. */
  readonly "storage.keys": Record<string, never>;
  /** Parameters of `http.fetch`. */
  readonly "http.fetch": {
    /** Original URL text matched against the declared rules. */
    readonly url: string;
    /** Method of the matching rule. */
    readonly method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
    /** Type of the request body, sent as the raw payload ≤ `MAX_HTTP_REQUEST_BYTES`. */
    readonly contentType?: "application/json" | "text/plain";
    /** `image` decodes the body in the host and returns an `asset:` handle. */
    readonly as: "json" | "text" | "bytes" | "image";
  };
  /** Parameters of `clipboard.writeText`. */
  readonly "clipboard.writeText": {
    /** Text. */
    readonly text: string;
  };
  /** Parameters of `links.open`. */
  readonly "links.open": {
    /** Absolute `https` address of a page a link rule allows. */
    readonly url: string;
  };
  /** Parameters of `gameEvents.warframe.subscribe`. */
  readonly "gameEvents.warframe.subscribe": Record<string, never>;
  /** Parameters of `session.subscribe`. */
  readonly "session.subscribe": Record<string, never>;
  /** Parameters of `game.subscribe`. */
  readonly "game.subscribe": Record<string, never>;
  /** Parameters of `telemetry.subscribe`. */
  readonly "telemetry.subscribe": Record<string, never>;
  /** Parameters of `fps.subscribe`. */
  readonly "fps.subscribe": Record<string, never>;
  /** Parameters of `media.subscribe`. */
  readonly "media.subscribe": {
    /** Request the cover art; default `true`. `false` stops the host from loading it. */
    readonly cover?: boolean;
  };
  /** Parameters of `media.previous`. */
  readonly "media.previous": {
    /** Player ID from `media.subscribe`; guards against a player change. */
    readonly player?: string;
  };
  /** Parameters of `media.playPause`. */
  readonly "media.playPause": {
    /** Player ID from `media.subscribe`; guards against a player change. */
    readonly player?: string;
  };
  /** Parameters of `media.next`. */
  readonly "media.next": {
    /** Player ID from `media.subscribe`; guards against a player change. */
    readonly player?: string;
  };
  /** Parameters of `stopwatch.subscribe`. */
  readonly "stopwatch.subscribe": Record<string, never>;
  /** Parameters of `stopwatch.toggle`. */
  readonly "stopwatch.toggle": Record<string, never>;
  /** Parameters of `stopwatch.reset`. */
  readonly "stopwatch.reset": Record<string, never>;
  /** Parameters of `notes.subscribe`. */
  readonly "notes.subscribe": Record<string, never>;
  /** Parameters of `notes.create`. */
  readonly "notes.create": Record<string, never>;
  /** Parameters of `notes.select`. */
  readonly "notes.select": {
    /** Note ID. */
    readonly note: string;
  };
  /** Parameters of `notes.setItem`. */
  readonly "notes.setItem": {
    /** Note ID. */
    readonly note: string;
    /** Checklist item ID. */
    readonly item: string;
    /** New state. */
    readonly checked: boolean;
  };
  /** Parameters of `notes.delete`. */
  readonly "notes.delete": {
    /** Note ID. */
    readonly note: string;
  };
  /** Parameters of `playervox.score.subscribe`. */
  readonly "playervox.score.subscribe": Record<string, never>;
  /** Parameters of `playervox.rating.subscribe`. */
  readonly "playervox.rating.subscribe": Record<string, never>;
  /** Parameters of `playervox.reviews.subscribe`. */
  readonly "playervox.reviews.subscribe": Record<string, never>;
  /** Parameters of `playervox.reviews.page`. */
  readonly "playervox.reviews.page": {
    /** Page number; default 1. */
    readonly page?: number;
    /** Only reviews of followed players; default `false`. */
    readonly followedOnly?: boolean;
  };
  /** Parameters of `journal.subscribe`. */
  readonly "journal.subscribe": Record<string, never>;
  /** Parameters of `journal.page`. */
  readonly "journal.page": {
    /** Opaque page cursor; absent for the first page. */
    readonly cursor?: string;
  };
  /** Parameters of `journal.delete`. */
  readonly "journal.delete": {
    /** Journal session ID. */
    readonly session: string;
  };
  /** Parameters of `twitch.chat.subscribe`. */
  readonly "twitch.chat.subscribe": Record<string, never>;
  /** Parameters of `twitch.chat.join`. */
  readonly "twitch.chat.join": {
    /** Channel login. */
    readonly channel: string;
  };
  /** Parameters of `twitch.chat.leave`. */
  readonly "twitch.chat.leave": Record<string, never>;
  /** Parameters of `twitch.chat.favorite`. */
  readonly "twitch.chat.favorite": {
    /** Channel login. */
    readonly channel: string;
    /** Add or remove. */
    readonly favorite: boolean;
  };
  /** Parameters of `account.subscribe`. */
  readonly "account.subscribe": {
    /** `id` of an account the manifest declares, or of the integrated service it names, that the user granted. */
    readonly id: string;
  };
  /** Parameters of `twitch.events.subscribe`. */
  readonly "twitch.events.subscribe": {
    /** Distinct event types among the declaration's `events`; default all of them. A type it does not list fails with `permission_denied`. */
    readonly types?: readonly string[];
  };
  /** Parameters of `steam.events.subscribe`. */
  readonly "steam.events.subscribe": {
    /** The SteamID64 of the account the widget follows: 17 digits, an individual account. Another value fails with `invalid_request`. */
    readonly steamid: string;
    /** Distinct event types among the declaration's `events`; default all of them. A type it does not list fails with `permission_denied`. */
    readonly types?: readonly string[];
  };
  /** Parameters of `steam.achievements.local`. */
  readonly "steam.achievements.local": {
    /** The SteamID64 of the account the widget follows: 17 digits, an individual account. Another value fails with `invalid_request`. */
    readonly steamid: string;
    /** The game's Steam app ID. */
    readonly appid: number;
    /** How many achievements of the order to skip, for the next page; default 0. */
    readonly offset?: number;
  };
  /** Parameters of `account.connect`. */
  readonly "account.connect": {
    /** `id` of an account the manifest declares, or of the integrated service it names, that the user granted. */
    readonly id: string;
  };
}

/** The result of each call, and each update of each subscription. */
export interface ServiceResultMap {
  /** `subscription.cancel`: `null`. */
  readonly "subscription.cancel": null;
  /** `timer.start`: `null`; ticks arrive as `timer` events, never while hidden. */
  readonly "timer.start": null;
  /** `timer.cancel`: `null`. */
  readonly "timer.cancel": null;
  /** `storage.get`: stored JSON value or `null`. */
  readonly "storage.get": JsonValue;
  /** `storage.set`: `null`; `quota_exceeded` beyond `STORAGE_QUOTA_BYTES`. */
  readonly "storage.set": null;
  /** `storage.remove`: `null`. */
  readonly "storage.remove": null;
  /** `storage.keys`: list of keys. */
  readonly "storage.keys": ReadonlyArray<string>;
  /** `http.fetch`: `{ status, contentType, headers }` with the body as raw payload ≤ the rule's `maxResponseBytes` (`MAX_HTTP_RESPONSE_BYTES` when absent), or `{ status, asset, headers }` from a body ≤ `MAX_HTTP_RESPONSE_BYTES`; `headers` holds the response's headers of `RESPONSE_HEADERS` only; on a rule that names an account, `not_connected` while it is not connected and `account_refused` when the service refused its secret. */
  readonly "http.fetch": HttpResponse;
  /** `clipboard.writeText`: `null`. */
  readonly "clipboard.writeText": null;
  /** `links.open`: `null` once the host handed the address to the browser. The host shows the address and, the first time for its origin, asks the user, who may later take that back in the Control Center; `cancelled` when the user declines; `permission_denied` for an address no rule allows; `url_invalid` for one that is not a plain HTTPS address (credentials, a path with encoded or dot segments, beyond `MAX_LINK_URL_BYTES`); `busy` while a confirmation is open; `unavailable` when no browser could open it. */
  readonly "links.open": null;
  /** `gameEvents.warframe.subscribe`: `{ playing, session, features, info, events }` at once, then at each change of what the widget follows; `permission_denied` when `gameEvents` lists no `warframe.*` feature. `playing` says whether Warframe is the active game; `session` is the launch of Warframe, which changes at each launch; `features` gives each feature's status; `info` the state of each feature the widget follows, ready to show (`null` for the others and while nothing is known); `events` repeats the latest `SERVICE_EVENT_WINDOW` events of those features, oldest first, each `{ seq, at, type }` and the state its type names: updates are coalesced, so take only those whose `seq` is above the last one seen. At most one subscription per widget at a time: another fails with `busy`. */
  readonly "gameEvents.warframe.subscribe": WarframeEvents;
  /** `session.subscribe`: `{ elapsedMs, at }` counted from the start of the game process, or `null` without an active game. */
  readonly "session.subscribe": Session | null;
  /** `game.subscribe`: `{ steamAppId, name }` of the active game, or `null` without one: `steamAppId` is the game's Steam app ID, `null` for a game outside the Steam store (a game added by hand, a non-Steam shortcut), and `name` the game's name in the user's game list, `null` when the host has none. */
  readonly "game.subscribe": Game | null;
  /** `telemetry.subscribe`: `{ cpu, ram, cpuTemperature, gpuTemperature, sources }`, or `null` without an active game: `cpu` is the game's share of the whole machine in % (0–100), `ram` its resident bytes, temperatures are °C or `null`, `sources` `{ cpuTemperature, gpuTemperature }` says whether the host has each sensor. */
  readonly "telemetry.subscribe": Telemetry | null;
  /** `fps.subscribe`: `{ fps, stale, status }`: `fps` a number or `null`; the host sets `stale` 3 s after the last sample; `status` is `ready`, `waiting`, `unsupported`, `permission_denied`, `ambiguous`, `events_lost` or `unavailable`. */
  readonly "fps.subscribe": Fps;
  /** `media.subscribe`: `null` without a player, or `{ player, title, artists, playing, canPrevious, canPlayPause, canNext, cover }`: `player` an opaque ID, `artists` a list, `cover` an `asset:` handle of at most 512 px or `null`. */
  readonly "media.subscribe": Media | null;
  /** `media.previous`: `null`; `stale_context` when `player` is no longer current. */
  readonly "media.previous": null;
  /** `media.playPause`: `null`; `stale_context` when `player` is no longer current. */
  readonly "media.playPause": null;
  /** `media.next`: `null`; `stale_context` when `player` is no longer current. */
  readonly "media.next": null;
  /** `stopwatch.subscribe`: `{ running, elapsedMs, at, shortcuts }`, or `null` without an active game; `shortcuts` `{ toggle, reset, bound }` holds host-formatted key chords. */
  readonly "stopwatch.subscribe": Stopwatch | null;
  /** `stopwatch.toggle`: the new state, as in `stopwatch.subscribe`; `unavailable` when the host cannot act. */
  readonly "stopwatch.toggle": Stopwatch | null;
  /** `stopwatch.reset`: the new state, as in `stopwatch.subscribe`; `unavailable` when the host cannot act. */
  readonly "stopwatch.reset": Stopwatch | null;
  /** `notes.subscribe`: `{ active, notes }` of the user's single notes document; each note `{ id, title, body, items }`, each item `{ id, text, checked }`. */
  readonly "notes.subscribe": Notes;
  /** `notes.create`: `{ note }`, a new empty active note titled `Note {n}` in the user's language; `quota_exceeded` beyond `MAX_NOTES`. */
  readonly "notes.create": CreatedNote;
  /** `notes.select`: `null`; the host stores the active note. */
  readonly "notes.select": null;
  /** `notes.setItem`: `null`. */
  readonly "notes.setItem": null;
  /** `notes.delete`: `null`, or `cancelled` when the user declines. */
  readonly "notes.delete": null;
  /** `playervox.score.subscribe`: `{ state, name, score, grade, ratingsCount, criteria }`: `state` is `idle`, `unsupported`, `loading`, `ready`, `no_ratings`, `not_found` or `unavailable`; `criteria` `{ gameplay, art, tech }`, each 0–100 or `null`. */
  readonly "playervox.score.subscribe": Score;
  /** `playervox.rating.subscribe`: `{ state, name, offline, rating }`: `state` is `idle`, `unsupported`, `loading`, `ready` or `unavailable`; `rating` is `null` before the user's first rating, or `{ gameplay, art, tech, review, publishedAt, offsetMinutes }`. Nothing is sent while the PlayerVox account is signed out, pending or expired. A published rating is sent again by the subscription. The host seeds the `playervox.rating.publish` controls from it. */
  readonly "playervox.rating.subscribe": RatingState;
  /** `playervox.reviews.subscribe`: `{ state, revision, offline }`: `state` is `idle`, `unsupported` or `ready`; `revision` changes whenever the reviews to read change (another game, another PlayerVox account, reviews changed on PlayerVox), so the widget reads its page again; `offline` while PlayerVox is unreachable. Nothing is sent while the PlayerVox account is signed out, pending or expired. Holding this subscription is what keeps the host's reviews source running. */
  readonly "playervox.reviews.subscribe": ReviewsState;
  /** `playervox.reviews.page`: `{ gameName, items, page, totalPages, count }`: three reviews of the active game per page, in the language of the host's interface; a page past the end answers the last page; each item `{ id, author, grade, score, text, original, hidden, publishedAt, offsetMinutes }`, `text` translated when a translation exists, `original` the untranslated text of a translated review or `null`, both cut by the host to `MAX_NODE_TEXT_BYTES`. Each call reads its own page: the host keeps no page position or filter shared between widgets. */
  readonly "playervox.reviews.page": ReviewsPage;
  /** `journal.subscribe`: `null` without an active game, or `{ revision, notice }`: `revision` changes whenever the merged journal of the active game changes (a session recorded or deleted, cloud sessions merged, the PlayerVox account or sync changed), so the widget reads its page again; `notice` is `null`, `offline`, `storage_unavailable`, `full`, `expired`, `busy` or `unavailable`. Holding this subscription is what keeps the host's journal source running. */
  readonly "journal.subscribe": JournalState | null;
  /** `journal.page`: `{ gameName, items, page, next, previous }`: five local and cloud sessions of the active game, merged and deduplicated, newest first; without `cursor`, the first page; each item `{ id, startedAt, offsetMinutes, durationMs, source }`; cursors are host handles that stay valid for the widget whatever other widgets read, and a cursor past the end answers the last page. */
  readonly "journal.page": JournalPage;
  /** `journal.delete`: `null`, or `cancelled` when the user declines; `not_connected` for a cloud session while PlayerVox is disconnected. */
  readonly "journal.delete": null;
  /** `twitch.chat.subscribe`: `{ account, channel, joinState, failure, favorites, canSend, generation, reset, messages, removed, skipped }`: `account` is `signed_out`, `pending`, `connected` or `expired` (sign-in is host chrome); `failure` is the fixed category of a `failed` join; messages arrive as deltas, at most one update per 100 ms, with `reset` after subscribing, a generation change or a show, and nothing while the widget is hidden; a faster chat is sampled, `skipped` counting the new messages left out; each message `{ id, author, color, badges, fragments, reply, deleted, receivedAt }` with at most `MAX_CHAT_FRAGMENTS` fragments, emotes and badges as `asset:` handles for the current theme and scale. */
  readonly "twitch.chat.subscribe": TwitchChat;
  /** `twitch.chat.join`: `null`; the host remembers the channel and rejoins it when the widget starts. */
  readonly "twitch.chat.join": null;
  /** `twitch.chat.leave`: `null`; the host forgets the channel. */
  readonly "twitch.chat.leave": null;
  /** `twitch.chat.favorite`: `null`; `quota_exceeded` beyond `MAX_CHAT_FAVORITES`. */
  readonly "twitch.chat.favorite": null;
  /** `account.subscribe`: `{ state }` at once, then at each change: `signed_out`, `pending` (a sign-in step is open), `connected`, `refused` (the service refused the key) or `expired` (the service asks to sign in again). The widget never sees the secret, the account's name or its scopes; with `required`, the host covers the content until the account is connected. */
  readonly "account.subscribe": AccountStatus;
  /** `twitch.events.subscribe`: `{ state, reason, events }` at once, then at each change. `state` is `live` once the host has subscribed at Twitch, `off` otherwise, with `reason` `connecting`, `not_connected` (Twitch is not connected, or its connection lacks a declared scope) or `unavailable` (Twitch refused or cannot be reached; the host retries). Twitch replays nothing: at each `live`, read once by `http.fetch` what changed meanwhile, and keep reading while `off`. `events` repeats the latest `SERVICE_EVENT_WINDOW` events of the subscription, oldest first, each `{ seq, type, at, data }`: updates are coalesced, so take only those whose `seq` is above the last one seen; a gap in `seq` means events were missed (read again). `data` is the host's projection of Twitch's event: every field of the type's table, `null` where Twitch sent none. */
  readonly "twitch.events.subscribe": TwitchEvents;
  /** `steam.events.subscribe`: `{ state, reason, events }` at once, then at each change. `state` is `live` while the host watches the Steam client's stats on this computer, `off` otherwise, with `reason` `connecting`, `not_connected` (Steam is not connected) or `unavailable` (no Steam client found on this computer). Steam pushes nothing and the host replays nothing: the events only say when to read again by `http.fetch`, and the widget keeps reading at its own pace too (Steam may run on another computer). `events` repeats the latest `SERVICE_EVENT_WINDOW` events of the subscription, oldest first, each `{ seq, type, at, data }`: updates are coalesced, so take only those whose `seq` is above the last one seen; a gap in `seq` means events were missed (read again). `stats.saved`: the Steam client saved the stats of a game of that account, at each achievement unlocked and at other times; `data` is `{ appid }`, `at` the time of the save. At most one subscription per widget at a time: another fails with `busy`. */
  readonly "steam.events.subscribe": SteamEvents;
  /** `steam.achievements.local`: `{ appid, total, achievements }`: the achievements of that game the Steam client of this computer saved as unlocked for that account, read-only from its own stats files, even before Steam publishes them online and whatever the game details' privacy. `total` counts them all; `achievements` gives at most `MAX_LOCAL_ACHIEVEMENTS` from `offset`, newest first, each `{ name, unlockedAt }`: the API name, as `GetSchemaForGame` and `GetPlayerAchievements` give it, and the unlock time in Unix milliseconds, `null` when Steam saved none. Nothing else of the files. An empty list: no achievement unlocked yet. Needs the declaration's `local: ["achievements"]` (`permission_denied` without), not a connected key. `unavailable` when the computer has no Steam client, no stats of that account and game, or files the host cannot read or does not know: keep reading Steam's Web API. One call per widget at a time: another fails with `busy`. */
  readonly "steam.achievements.local": SteamLocalAchievements;
  /** `account.connect`: `null`; the host shows its account panel for this account, in its current state: the widget's own button for an account that is not `required`. */
  readonly "account.connect": null;
}

/** Services answered once. */
export type CallServiceName =
  | "subscription.cancel"
  | "timer.start"
  | "timer.cancel"
  | "storage.get"
  | "storage.set"
  | "storage.remove"
  | "storage.keys"
  | "http.fetch"
  | "clipboard.writeText"
  | "links.open"
  | "media.previous"
  | "media.playPause"
  | "media.next"
  | "stopwatch.toggle"
  | "stopwatch.reset"
  | "notes.create"
  | "notes.select"
  | "notes.setItem"
  | "notes.delete"
  | "playervox.reviews.page"
  | "journal.page"
  | "journal.delete"
  | "twitch.chat.join"
  | "twitch.chat.leave"
  | "twitch.chat.favorite"
  | "steam.achievements.local"
  | "account.connect";

/** Services that send updates until cancelled. */
export type SubscribeServiceName =
  | "gameEvents.warframe.subscribe"
  | "session.subscribe"
  | "game.subscribe"
  | "telemetry.subscribe"
  | "fps.subscribe"
  | "media.subscribe"
  | "stopwatch.subscribe"
  | "notes.subscribe"
  | "playervox.score.subscribe"
  | "playervox.rating.subscribe"
  | "playervox.reviews.subscribe"
  | "journal.subscribe"
  | "twitch.chat.subscribe"
  | "account.subscribe"
  | "twitch.events.subscribe"
  | "steam.events.subscribe";

/** Services accepted only while a gesture event is handled. */
export type GestureServiceName =
  | "clipboard.writeText"
  | "links.open"
  | "media.previous"
  | "media.playPause"
  | "media.next"
  | "stopwatch.toggle"
  | "stopwatch.reset"
  | "notes.create"
  | "notes.select"
  | "notes.setItem"
  | "notes.delete"
  | "journal.delete"
  | "twitch.chat.join"
  | "twitch.chat.leave"
  | "twitch.chat.favorite"
  | "account.connect";
